import type { PlacementDrive } from './placement-drive-model';
import type { Skill } from './skill-model';

export const DriveRequirementMinimumProficiencyKeyToLabel = {
  'MinimumProficiencyKey0': 'Beginner',
  'MinimumProficiencyKey1': 'Intermediate',
  'MinimumProficiencyKey2': 'Advanced'
} as const;
export type DriveRequirementMinimumProficiencyKey = keyof typeof DriveRequirementMinimumProficiencyKeyToLabel;

export interface DriveRequirement {
  /**
   * @displayName Drive Requirement ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Requirement Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  requirementName: string;
  /**
   * @displayName Is Mandatory
   * @validationRule Required for create/update operations
   */
  isMandatory: boolean;
  /**
   * @displayName Minimum Proficiency
   * @validationRule Required for create/update operations
   */
  minimumProficiencyKey: DriveRequirementMinimumProficiencyKey;
  /**
   * @displayName Placement Drive
   * @validationRule Required for create/update operations
   */
  placementDrive: Pick<PlacementDrive, 'id' | 'companyName'>;
  /**
   * @displayName Skill
   * @validationRule Required for create/update operations
   */
  skill: Pick<Skill, 'id' | 'name1'>;
}

export const _DriveRequirement = 'DriveRequirement' as const;
